'use strict';

// MODULES //

var tape = require( 'tape' );
var isSameFloat64Array = require( '@stdlib/assert/is-same-float64array' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var Float64Array = require( '@stdlib/array/float64' );
var cround = require( './../lib/assign.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof cround, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function rounds each component of a double-precision complex floating-point number to the nearest integer', function test( t ) {
	var expected;
	var out;
	var v;

	out = new Float64Array( 2 );
	v = cround( -1.5, 2.5, out, 1, 0 );

	expected = new Float64Array( [ -1.0, 3.0 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	out = new Float64Array( 4 );
	v = cround( -1.5, 2.5, out, 2, 0 );

	expected = new Float64Array( [ -1.0, 0.0, 3.0, 0.0 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	out = new Float64Array( 4 );
	v = cround( -1.5, 2.5, out, 2, 1 );

	expected = new Float64Array( [ 0.0, -1.0, 0.0, 3.0 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	out = new Float64Array( 4 );
	v = cround( -1.5, 2.5, out, -2, 3 );

	expected = new Float64Array( [ 0.0, 3.0, 0.0, -1.0 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	t.end();
});

tape( 'the function rounds real and imaginary components to the nearest integer', function test( t ) {
	var expected;
	var out;

	out = new Float64Array( 2 );
	cround( -4.2, 5.5, out, 1, 0 );

	expected = new Float64Array( [ -4.0, 6.0 ] );

	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	out = new Float64Array( 2 );
	cround( 9.99999, 0.1, out, 1, 0 );

	expected = new Float64Array( [ 10.0, 0.0 ] );

	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	out = new Float64Array( 2 );
	cround( 0.0, 0.0, out, 1, 0 );

	expected = new Float64Array( [ 0.0, 0.0 ] );

	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns a `NaN` if provided a `NaN`', function test( t ) {
	var out = new Float64Array( 2 );

	cround( NaN, NaN, out, 1, 0 );
	t.strictEqual( isnan( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnan( out[ 1 ] ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-0` if provided `-0`', function test( t ) {
	var expected;
	var out;

	out = new Float64Array( 2 );
	cround( -0.0, -0.0, out, 1, 0 );

	expected = new Float64Array( [ -0.0, -0.0 ] );

	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+0` if provided `+0`', function test( t ) {
	var expected;
	var out;

	out = new Float64Array( 2 );
	cround( +0.0, +0.0, out, 1, 0 );

	expected = new Float64Array( [ +0.0, +0.0 ] );

	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+infinity` if provided `+infinity`', function test( t ) {
	var expected;
	var out;

	out = new Float64Array( 2 );
	cround( PINF, PINF, out, 1, 0 );

	expected = new Float64Array( [ PINF, PINF ] );

	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-infinity` if provided `-infinity`', function test( t ) {
	var expected;
	var out;

	out = new Float64Array( 2 );
	cround( NINF, NINF, out, 1, 0 );

	expected = new Float64Array( [ NINF, NINF ] );

	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );
	t.end();
});
